    log_file = TimedRotatingFileHandler(filename, mode=mode, date_format=date_format, bubble=bubble, encoding=encoding)
    log_formatter = norm_log_type if log_type == 'norm' else sys_log_type
    log_file.formatter = log_formatter
    log_std = ColorizedStderrHandler(bubble=bubble)
    log_std.formatter = log_formatter
    run_log = Logger('script_log')
    set_datetime_format('local')
    run_log.handlers = []
    run_log.handlers.append(log_file)
    run_log.handlers.append(log_std)
    for log_handler in (strategy_log, system_log, user_log):
        log_handler.remove_handlers()
        log_handler.add_handler(log_file)
        log_handler.add_handler(log_std)
    logbook_handler = LogbookHandler(run_log)
    logbook_handler.setLevel(logging.DEBUG)
    for tornado_logger in (access_log, app_log, gen_log):
        tornado_logger.setLevel(logging.DEBUG)
        tornado_logger.handlers = []
        tornado_logger.addHandler(logbook_handler)
