    if isinstance(l, str):
        l = l.replace('.XSHE', '.SZ')
        l = l.replace('.XSHG', '.SS')
        check_stock(l)
        return None
    elif isinstance(l, list) or isinstance(l, tuple):
        for s in l:
            s = s.replace('.XSHE', '.SZ')
            s = s.replace('.XSHG', '.SS')
            check_stock(s)
